// Dev only: /dev/items/compare puts each catalogue card twice side by side: with the app's own line
// drawing (src/items/arts.ts, drawn by Claude) and with its QuiverAI picture: the shipped one
// (src/items/pictures/, as the app shows it) or, before item-arts-ship.mjs, the raw one generated by
// scripts/item-arts-quiver.mjs into decor-review/quiver/ (gitignored, served by the dev server).
// No Supabase. The skin toggle at the top switches Art Deco / Classic.
import { useEffect, useState } from 'react'
import { SkinToggle } from '@/theme/Masthead'
import { CATALOG_BY_ID } from './catalog'
import { ItemCard } from './ItemCard'
import { PICTURES } from './pictures'

interface Generated {
  model: string
  prompt: string
  usage: { input_tokens?: number; output_tokens?: number } | null
  sandbox: boolean
  createdAt: string
}
type Manifest = { cards: Record<string, Generated> }

const DIR = '/decor-review/quiver'

export function ItemsCompare() {
  const [manifest, setManifest] = useState<Manifest | null | 'none'>(null)
  useEffect(() => {
    fetch(`${DIR}/manifest.json`, { cache: 'no-store' })
      .then((r) => (r.ok ? r.json() : 'none'))
      .then((m: Manifest | 'none') => setManifest(m))
      .catch(() => setManifest('none'))
  }, [])

  const entries = manifest && manifest !== 'none' ? Object.entries(manifest.cards).filter(([id]) => CATALOG_BY_ID.has(id)) : []
  const sandbox = entries.some(([, g]) => g.sandbox)
  const tokens = entries.reduce((n, [, g]) => n + (g.usage?.output_tokens ?? 0), 0)

  return (
    <main className="mx-auto flex max-w-6xl flex-col gap-6 p-6">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div className="flex flex-col gap-1">
          <p className="eyebrow">Dev · item cards</p>
          <h1 className="font-heading text-3xl">Claude’s drawings vs QuiverAI</h1>
          <p className="font-serif text-base text-muted-foreground">
            Left: the app’s line drawing. Right: QuiverAI, same style prompt. {entries.length ? `${entries.length} cards, ${tokens} output tokens.` : ''}
          </p>
        </div>
        <SkinToggle />
      </header>
      {manifest === 'none' && (
        <p role="alert" className="border border-gold/50 p-4 font-serif text-lg">
          Nothing generated yet. Run <code>QUIVERAI_API_KEY=… node scripts/item-arts-quiver.mjs</code> with the dev server up, then reload.
        </p>
      )}
      {sandbox && (
        <p role="alert" className="border border-destructive p-4 font-serif text-lg">
          These come from a test key: QuiverAI answers test keys (sk_test_…) with a “SANDBOX RESULT” placeholder, not a drawing. Rerun the script with a live key and <code>--force</code>.
        </p>
      )}
      <ul className="flex flex-col gap-10">
        {entries.map(([id, g]) => {
          const card = CATALOG_BY_ID.get(id)!.card
          const source = { kind: 'catalog', id } as const
          return (
            <li key={id} className="grid gap-4 border-t border-border pt-6 md:grid-cols-[15rem_15rem_minmax(0,1fr)]">
              <figure className="flex flex-col gap-2">
                <ItemCard card={card} source={source} artSrc={null} />
                <figcaption className="text-center text-xs tracking-[0.14em] text-muted-foreground uppercase">Claude (arts.ts)</figcaption>
              </figure>
              <figure className="flex flex-col gap-2">
                <ItemCard card={card} source={source} artSrc={PICTURES[id] ? undefined : `${DIR}/${id}.svg?v=${encodeURIComponent(g.createdAt)}`} />
                <figcaption className="text-center text-xs tracking-[0.14em] text-muted-foreground uppercase">
                  QuiverAI ({g.model}){g.sandbox ? ' · sandbox' : PICTURES[id] ? ' · shipped' : ' · not shipped'}
                </figcaption>
              </figure>
              <div className="flex flex-col gap-3 text-sm">
                <a href={`${DIR}/${id}.svg`} target="_blank" rel="noreferrer" className="block aspect-square max-w-64 border border-border bg-[repeating-conic-gradient(#ffffff10_0_25%,transparent_0_50%)] bg-[length:16px_16px]">
                  <img src={`${DIR}/${id}.svg?v=${encodeURIComponent(g.createdAt)}`} alt={`QuiverAI ${id}`} className="size-full object-contain" />
                </a>
                <p className="text-muted-foreground">
                  {g.usage?.input_tokens ?? '?'} in / {g.usage?.output_tokens ?? '?'} out tokens · {new Date(g.createdAt).toLocaleString()}
                </p>
                <details>
                  <summary className="cursor-pointer text-muted-foreground">Prompt</summary>
                  <p className="mt-2 font-serif">{g.prompt}</p>
                </details>
              </div>
            </li>
          )
        })}
      </ul>
    </main>
  )
}
